/**
 * Type of WordPress site stored in the database.
 *
 * Uses integer representation in the database for performance.
 */

public enum DbSiteType: Int64, Equatable, Hashable {
    
    case selfHosted = 0
    case wordPressCom = 1





}

#if compiler(>=6)
extension DbSiteType: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeDbSiteType: FfiConverterRustBuffer {
    typealias SwiftType = DbSiteType

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> DbSiteType {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .selfHosted
        
        case 2: return .wordPressCom
        
        default: throw UniffiInternalError.unexpectedEnumCase
