/**
 * Database table identifier.
 *
 * Represents all tables tracked in the cache database. This enum provides
 * a single source of truth for table names, ensuring consistency across
 * the codebase and preventing typos.
 *
 * Note: uniffi::Enum makes this type available to platform bindings but
 * without exposing any methods (which is intentional - we don't want
 * Kotlin/Swift to access table names directly).
 */

public enum DbTable: Equatable, Hashable {
    
    /**
     * Posts with edit context (full data for editing)
     */
    case postsEditContext
    /**
     * Posts with view context (public viewing data)
     */
    case postsViewContext
    /**
     * Posts with embed context (minimal data for embeds)
     */
    case postsEmbedContext
    /**
     * Post types with edit context (post type configuration data)
     */
    case postTypesEditContext
    /**
     * Media with edit context (full media data for editing)
     */
    case mediaEditContext
    /**
     * Self-hosted WordPress sites
     */
    case selfHostedSites
    /**
     * Database sites mapping table
     */
    case dbSites
    /**
     * Term relationships (post-category, post-tag associations)
     */
    case termRelationships
    /**
     * List metadata headers (pagination, version)
     */
    case listMetadata
    /**
     * List metadata items (entity IDs with ordering)
     */
    case listMetadataItems
    /**
     * List metadata sync state (idle, fetching, error)
     */
    case listMetadataState
    /**
     * Entity state tracking (missing, fetching, cached, stale, failed)
     */
    case entityState
    /**
     * WordPress.com sites
     */
    case wordPressComSites
    /**
     * WordPress.com accounts, which own account-level data such as the Reader
     */
    case wordPressComAccounts
    /**
     * Reader posts, one per post per account
     */
    case readerPosts
    /**
     * Reader streams (pagination and sync state)
     */
    case readerStreams
    /**
     * Posts in Reader streams, with their order
     */
    case readerStreamItems
    /**
     * What the saved posts service knows about an account besides its saved posts
     */
    case readerSavedState
    /**
     * Saved posts, one per save on the server, with what the user wants for each
     */
    case readerSavedPosts
    /**
     * The URLs the server stores as a saved post
     */
    case readerSavedPostUrls
    /**
     * Posts a Reader stream's page had that couldn't be read
     */
    case readerUnreadablePosts
    /**
     * What the user turned on or off in the Reader that the server doesn't have yet
     */
    case readerActions
    /**
     * The sites the user blocked in the Reader
     */
    case readerBlockedSites
    /**
     * The users the reader blocked, on this device
     */
    case readerBlockedUsers
    /**
     * The sites the account is a member of
     */
    case readerMemberSites
    /**
     * When each of a reader's lists was last fetched whole
     */
    case readerSyncTimes
    /**
     * Cards in a Reader stream that aren't posts
     */
    case readerStreamCards
    /**
     * The Reader menu, with the tags a reader follows
     */
    case readerMenuItems
    /**
     * The sites and feeds an account follows
     */
    case readerSubscriptions
    /**
     * What the Reader shows of a site or a feed besides its posts
     */
    case readerSites
    /**
     * Posts' comments, and comments written on this device
     */
    case readerComments
    /**
     * Where each post's comments are up to
     */
    case readerCommentThreads
    /**
     * What the device has of each saved post for reading with no connection
     */
    case readerSavedOffline
    /**
     * The stored images of saved posts
     */
    case readerOfflineFiles
    /**
     * WordPress.com notifications, one per note per account
     */
    case notifications
    /**
     * Notes a list of IDs had that never came whole
     */
    case notificationListedOnly
    /**
     * When each account's notifications were last synced and looked at
     */
    case notificationSyncState
    /**
     * Where each tab of each account's notifications is up to
     */
    case notificationTabState
    /**
     * Notes marked read or unread that the server doesn't have yet
     */
    case notificationReadChanges





}

