public 
enum SqliteDbError: Swift.Error, Equatable, Hashable {

    
    
    case SqliteError(String
    )
    case ConstraintViolation(String
    )
    case ForeignKeysUnavailable
    case TableNameMismatch(expected: DbTable, actual: DbTable
    )
    case PerPageMismatch(expected: Int64, actual: Int64
    )

    

    

    
}

