extension SqliteDbError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeSqliteDbError: FfiConverterRustBuffer {
    typealias SwiftType = SqliteDbError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> SqliteDbError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .SqliteError(
            try FfiConverterString.read(from: &buf)
            )
        case 2: return .ConstraintViolation(
            try FfiConverterString.read(from: &buf)
            )
        case 3: return .ForeignKeysUnavailable
        case 4: return .TableNameMismatch(
            expected: try FfiConverterTypeDbTable.read(from: &buf), 
            actual: try FfiConverterTypeDbTable.read(from: &buf)
            )
        case 5: return .PerPageMismatch(
            expected: try FfiConverterInt64.read(from: &buf), 
            actual: try FfiConverterInt64.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: SqliteDbError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .SqliteError(v1):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(v1, into: &buf)
            
        
        case let .ConstraintViolation(v1):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(v1, into: &buf)
            
        
        case .ForeignKeysUnavailable:
            writeInt(&buf, Int32(3))
        
        
        case let .TableNameMismatch(expected,actual):
            writeInt(&buf, Int32(4))
            FfiConverterTypeDbTable.write(expected, into: &buf)
            FfiConverterTypeDbTable.write(actual, into: &buf)
            
        
        case let .PerPageMismatch(expected,actual):
            writeInt(&buf, Int32(5))
            FfiConverterInt64.write(expected, into: &buf)
            FfiConverterInt64.write(actual, into: &buf)
            
        }
    }
}


